-- One-time import: Aichi-Nagoya 2026 Athletics players (photos already uploaded to S3).
-- Looks up the edition by name pattern rather than a hardcoded id, since local dev
-- and production edition ids/slugs have diverged (production has more editions,
-- and this one was renamed there, which regenerated its slug).
BEGIN;
DO $$
DECLARE target_id INT;
BEGIN
  SELECT id INTO target_id FROM game_editions WHERE name LIKE '%Aichi-Nagoya%2026%';
  IF target_id IS NULL THEN RAISE EXCEPTION 'Could not find the Aichi-Nagoya 2026 edition — check game_editions.name manually'; END IF;
END $$;
COMMIT;
